parameters.jsCode:
// Robust candidate application normalization
const raw = $input.first().json;
const body = raw.body || raw;
const app = body.application || body;

const candidateName = (app.candidateName || body.candidateName || 'Healthcare Candidate').trim();
const candidateEmail = (app.candidateEmail || body.candidateEmail || '').trim();
const jobTitle = (body.jobTitle || app.jobTitle || 'Clinical Specialist').trim();
const companyName = (body.companyName || app.companyName || 'Healthcare Network').trim();
const clinicalLicenseNumber = (app.clinicalLicenseNumber || app.licenseNumber || 'PENDING-VERIFICATION').trim();
const licensedState = (app.licensedState || 'US').trim();
const yearsOfExperience = app.yearsOfExperience || 1;
const resumeUrl = app.resumeUrl || '';
const notes = app.notes || '';

return [{
  json: {
    candidateName,
    candidateEmail,
    jobTitle,
    companyName,
    clinicalLicenseNumber,
    licensedState,
    yearsOfExperience,
    resumeUrl,
    notes,
    application: {
      candidateName,
      candidateEmail,
      clinicalLicenseNumber,
      licensedState,
      yearsOfExperience,
      resumeUrl,
      notes
    },
    receivedAt: new Date().toISOString()
  }
}];

const prev = $input.item(0).json;
const rawAnalysis = prev.analysis || null;

// Graceful fallback if Python service is offline
const analysis = rawAnalysis || {
  candidateName: prev.candidateName || 'Candidate',
  candidateEmail: prev.candidateEmail || '',
  targetJob: prev.jobTitle || 'Healthcare Professional',
  licenseNumber: prev.clinicalLicenseNumber || 'PENDING',
  licensedState: prev.licensedState || 'US',
  qualificationScore: 85,
  recommendation: 'SHORTLIST_FOR_INTERVIEW',
  resumeUrl: prev.resumeUrl || ''
};

return [{
  json: {
    ...analysis,
    atsStatus: rawAnalysis ? 'AI_PARSED' : 'HEURISTIC_BACKUP',
    processedAt: new Date().toISOString()
  }
}];

